corrected_code:
def get_tenant_api_quota(request, tenant_id):
    if not request.user.tenant_memberships.filter(tenant_id=tenant_id, is_admin=True).exists():
        return HttpResponseForbidden()
    quota = get_object_or_404(TenantApiQuota, tenant_id=tenant_id)
    return JsonResponse({
        'tenant_id': quota.tenant_id,
        'rate_limit_per_minute': quota.rate_limit,
        'secret_gateway_key': quota.gateway_key
    })
